     out.push_str(&format!("{:<w$}  {total:>width$}\n", "total", w = 10 + 2 + desc));
     out
 }
+
+/// Balances rolled up to the first `depth` levels of the account name, sorted by name, with zero roll-ups left out.
+///
+/// # Panics
+///
+/// Panics if `depth` is 0.
+pub fn category_totals(ledger: &Ledger, depth: usize) -> Vec<(String, Amount)> {
+    assert!(depth > 0, "depth must be at least 1");
+    let mut totals: BTreeMap<String, Amount> = BTreeMap::new();
+    for (account, balance) in ledger.balances() {
+        let rolled: Vec<&str> = account.split(':').take(depth).collect();
+        *totals.entry(rolled.join(":")).or_default() += balance;
+    }
+    totals.into_iter().filter(|(_, a)| *a != Amount::ZERO).collect()
+}
+
+#[cfg(test)]
+mod category_tests {
+    use super::*;
+    use ledger_core::Transaction;
+
+    #[test]
+    fn category_totals_roll_up_and_skip_zero() {
+        let mut ledger = Ledger::new();
+        ledger.record(Transaction::new("2024-01-05", "groceries").post("expenses:food:groceries", Amount::from_cents(1250)).post("assets:bank", Amount::from_cents(-1250))).unwrap();
+        ledger.record(Transaction::new("2024-01-09", "dinner and rent").post("expenses:food:restaurant", Amount::from_cents(800)).post("expenses:rent", Amount::from_cents(500)).post("assets:bank", Amount::from_cents(-1300))).unwrap();
+        ledger.record(Transaction::new("2024-01-10", "card").post("liabilities:card", Amount::from_cents(500)).post("liabilities:card:x", Amount::from_cents(-500))).unwrap();
+        assert_eq!(
+            category_totals(&ledger, 2),
+            vec![
+                ("assets:bank".to_string(), Amount::from_cents(-1300)),
+                ("expenses:food".to_string(), Amount::from_cents(2050)),
+                ("expenses:rent".to_string(), Amount::from_cents(500)),
+            ]
+        );
+        assert_eq!(
+            category_totals(&ledger, 1),
+            vec![
+                ("assets".to_string(), Amount::from_cents(-1300)),
+                ("expenses".to_string(), Amount::from_cents(2550)),
+            ]
+        );
+    }
+
+    #[test]
+    #[should_panic(expected = "depth must be at least 1")]
+    fn category_totals_zero_depth_panics() {
+        let ledger = Ledger::new();
+        let _ = category_totals(&ledger, 0);
+    }
+}

