+
+/// Account balances rolled up to the first `depth` levels of the account name, sorted by name, leaving out zero roll-ups. Panics if `depth` is 0.
+pub fn category_totals(ledger: &Ledger, depth: usize) -> Vec<(String, Amount)> {
+    assert!(depth > 0, "depth must be at least 1");
+    let mut totals: BTreeMap<String, Amount> = BTreeMap::new();
+    for (account, balance) in ledger.balances() {
+        let key: Vec<&str> = account.split(':').take(depth).collect();
+        *totals.entry(key.join(":")).or_default() += balance;
+    }
+    totals.into_iter().filter(|(_, total)| *total != Amount::ZERO).collect()
+}
+
+#[cfg(test)]
+mod category_totals_tests {
+    use super::*;
+    use ledger_core::Transaction;
+
+    fn amt(s: &str) -> Amount {
+        Amount::parse(s).unwrap()
+    }
+
+    fn sample() -> Ledger {
+        let mut l = Ledger::new();
+        l.record(Transaction::new("2024-01-05", "groceries").post("expenses:food:groceries", amt("30.00")).post("assets:bank", amt("-30.00"))).unwrap();
+        l.record(Transaction::new("2024-01-06", "bakery").post("expenses:food:bakery", amt("5.00")).post("assets:cash", amt("-5.00"))).unwrap();
+        l.record(Transaction::new("2024-01-07", "rent").post("expenses:rent", amt("100.00")).post("assets:bank", amt("-100.00"))).unwrap();
+        l.record(Transaction::new("2024-01-08", "refund").post("expenses:food:bakery", amt("-5.00")).post("income:refunds", amt("5.00"))).unwrap();
+        l
+    }
+
+    #[test]
+    fn rolls_up_to_depth_and_drops_zero_totals() {
+        let l = sample();
+        assert_eq!(category_totals(&l, 2), vec![
+            ("assets:bank".to_string(), amt("-130.00")),
+            ("assets:cash".to_string(), amt("-5.00")),
+            ("expenses:food".to_string(), amt("30.00")),
+            ("expenses:rent".to_string(), amt("100.00")),
+            ("income:refunds".to_string(), amt("5.00")),
+        ]);
+        // expenses:food:bakery nets to zero, so it is left out at depth 3
+        assert_eq!(category_totals(&l, 3), vec![
+            ("assets:bank".to_string(), amt("-130.00")),
+            ("assets:cash".to_string(), amt("-5.00")),
+            ("expenses:food:groceries".to_string(), amt("30.00")),
+            ("expenses:rent".to_string(), amt("100.00")),
+            ("income:refunds".to_string(), amt("5.00")),
+        ]);
+    }
+
+    #[test]
+    #[should_panic]
+    fn zero_depth_panics() {
+        category_totals(&sample(), 0);
+    }
+}

